class Solution:
    def minimumOneBitOperations(self, n: int) -> int:
        res = n
        while n:
            n >>= 1
            res ^= n
        return res

code.cpp:
class Solution {
public:
    int minimumOneBitOperations(int n) {
        int res = n;
        while (n != 0) {
            n >>= 1;
            res ^= n;
        }
        return res;
    }
};
